/* ===== BLOG DE ANA ALMEIDA - JAVASCRIPT ===== */

// Lista dos posts com imagens e informações
const postsData = [
  {
      id: 1,
          title: 'Romance Contemporâneo: Emoções e Realidade',
              author: 'Ana Almeida',
                  tags: ['romance', 'contemporâneo'],
                      content: 'Discussão sobre as principais obras do romance moderno e suas temáticas humanas.',
                          image: 'https://m.media-amazon.com/images/I/71xjJmDgT0L.jpg' // A culpa é das estrelas
                            },
                              {
                                  id: 2,
                                      title: 'Fantasia Épica e Construção de Mundos',
                                          author: 'Ana Almeida',
                                              tags: ['fantasia', 'épico'],
                                                  content: 'Explorando o poder da imaginação e os universos complexos de autores como Tolkien e Sanderson.',
                                                      image: 'https://m.media-amazon.com/images/I/81iqZ2HHD-L.jpg' // Harry Potter
                                                        },
                                                          {
                                                              id: 3,
                                                                  title: 'Mistério e Suspense',
                                                                      author: 'Ana Almeida',
                                                                          tags: ['suspense', 'mistério'],
                                                                              content: 'Como autores como Agatha Christie e Arthur Conan Doyle dominam a arte de manter o leitor intrigado.',
                                                                                  image: 'https://m.media-amazon.com/images/I/81gTwYAhU7L.jpg' // O Assassinato no Expresso do Oriente
                                                                                    },
                                                                                      {
                                                                                          id: 4,
                                                                                              title: 'A Poesia Moderna',
                                                                                                  author: 'Ana Almeida',
                                                                                                      tags: ['poesia', 'literatura'],
                                                                                                          content: 'Reflexão sobre o papel da poesia na contemporaneidade e seus principais representantes.',
                                                                                                              image: 'https://m.media-amazon.com/images/I/71g2ednj0JL.jpg' // Poesia que Transforma
                                                                                                                },
                                                                                                                  {
                                                                                                                      id: 5,
                                                                                                                          title: 'Ficção Científica e Futuro da Sociedade',
                                                                                                                              author: 'Ana Almeida',
                                                                                                                                  tags: ['ficção científica', 'tecnologia'],
                                                                                                                                      content: 'Um olhar sobre as obras que imaginam o futuro e questionam o presente.',
                                                                                                                                          image: 'https://m.media-amazon.com/images/I/81YOuOGFCJL.jpg' // Duna
                                                                                                                                            }
                                                                                                                                            ];

                                                                                                                                            // Função para normalizar texto (remove acentos e coloca em minúsculo)
                                                                                                                                            function normalize(str) {
                                                                                                                                              return str
                                                                                                                                                  ? str.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase()
                                                                                                                                                      : '';
                                                                                                                                                      }

                                                                                                                                                      // Elementos principais do DOM
                                                                                                                                                      const postsEl = document.getElementById('posts');
                                                                                                                                                      const countEl = document.getElementById('count');
                                                                                                                                                      const noResultsEl = document.getElementById('noResults');
                                                                                                                                                      const searchInput = document.getElementById('searchInput');
                                                                                                                                                      const clearBtn = document.getElementById('clearBtn');

                                                                                                                                                      // Renderizar posts na página
                                                                                                                                                      function render(list, query) {
                                                                                                                                                        postsEl.innerHTML = '';

                                                                                                                                                          if (!list.length) {
                                                                                                                                                              noResultsEl.style.display = 'block';
                                                                                                                                                                  countEl.textContent = '0';
                                                                                                                                                                      return;
                                                                                                                                                                        }

                                                                                                                                                                          noResultsEl.style.display = 'none';
                                                                                                                                                                            countEl.textContent = String(list.length);

                                                                                                                                                                              list.forEach((p) => {
                                                                                                                                                                                  const div = document.createElement('article');
                                                                                                                                                                                      div.className = 'post';
                                                                                                                                                                                          div.id = p.tags[0];

                                                                                                                                                                                              function highlight(text) {
                                                                                                                                                                                                    if (!query) return escapeHtml(text);
                                                                                                                                                                                                          const q = escapeRegExp(query.trim());
                                                                                                                                                                                                                const re = new RegExp('(' + q + ')', 'ig');
                                                                                                                                                                                                                      return escapeHtml(text).replace(re, '<span class="highlight">$1</span>');
                                                                                                                                                                                                                          }

                                                                                                                                                                                                                              div.innerHTML = `
                                                                                                                                                                                                                                    <img src="${p.image}" alt="Capa do livro ${p.title}">
                                                                                                                                                                                                                                          <div class="post-content">
                                                                                                                                                                                                                                                  <h2>${highlight(p.title)}</h2>
                                                                                                                                                                                                                                                          <p><strong>Autor:</strong> ${highlight(p.author)}</p>
                                                                                                                                                                                                                                                                  <p>${highlight(p.content)}</p>
                                                                                                                                                                                                                                                                          <div class="tags">${p.tags
                                                                                                                                                                                                                                                                                    .map((t) => `<span class="tag">${highlight(t)}</span>`)
                                                                                                                                                                                                                                                                                              .join('')}</div>
                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                            postsEl.appendChild(div);
                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                              // Escapar caracteres HTML e regex
                                                                                                                                                                                                                                                                                                              function escapeHtml(unsafe) {
                                                                                                                                                                                                                                                                                                                return unsafe
                                                                                                                                                                                                                                                                                                                    .replace(/&/g, '&amp;')
                                                                                                                                                                                                                                                                                                                        .replace(/</g, '&lt;')
                                                                                                                                                                                                                                                                                                                            .replace(/>/g, '&gt;')
                                                                                                                                                                                                                                                                                                                                .replace(/"/g, '&quot;')
                                                                                                                                                                                                                                                                                                                                    .replace(/'/g, '&#039;');
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    function escapeRegExp(string) {
                                                                                                                                                                                                                                                                                                                                      return String(string).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                      // Função de busca
                                                                                                                                                                                                                                                                                                                                      function searchPosts(rawQuery) {
                                                                                                                                                                                                                                                                                                                                        const scope = document.getElementById('scope').value;
                                                                                                                                                                                                                                                                                                                                          const tagFilter = normalize(document.getElementById('tagFilter').value.trim());
                                                                                                                                                                                                                                                                                                                                            const matchWhole = document.getElementById('matchWhole').checked;
                                                                                                                                                                                                                                                                                                                                              const q = normalize(rawQuery);

                                                                                                                                                                                                                                                                                                                                                if (!q && !tagFilter) {
                                                                                                                                                                                                                                                                                                                                                    render(postsData);
                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                            const results = postsData.filter((p) => {
                                                                                                                                                                                                                                                                                                                                                                const nTitle = normalize(p.title),
                                                                                                                                                                                                                                                                                                                                                                      nAuthor = normalize(p.author),
                                                                                                                                                                                                                                                                                                                                                                            nContent = normalize(p.content),
                                                                                                                                                                                                                                                                                                                                                                                  nTags = p.tags.map(normalize);

                                                                                                                                                                                                                                                                                                                                                                                      if (tagFilter && !nTags.some((t) => t.includes(tagFilter))) return false;
                                                                                                                                                                                                                                                                                                                                                                                          if (!q) return true;

                                                                                                                                                                                                                                                                                                                                                                                              if (matchWhole) {
                                                                                                                                                                                                                                                                                                                                                                                                    const wordRe = new RegExp('\\b' + escapeRegExp(q) + '\\b');
                                                                                                                                                                                                                                                                                                                                                                                                          if (scope === 'all')
                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                            wordRe.test(nTitle) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                      wordRe.test(nAuthor) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                wordRe.test(nContent) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                          nTags.some((t) => wordRe.test(t))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (scope === 'title') return wordRe.test(nTitle);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (scope === 'author') return wordRe.test(nAuthor);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (scope === 'content') return wordRe.test(nContent);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (scope === 'tags') return nTags.some((t) => wordRe.test(t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (scope === 'all')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      nTitle.includes(q) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              nAuthor.includes(q) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      nContent.includes(q) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              nTags.some((t) => t.includes(q))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (scope === 'title') return nTitle.includes(q);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (scope === 'author') return nAuthor.includes(q);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (scope === 'content') return nContent.includes(q);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (scope === 'tags') return nTags.some((t) => t.includes(q));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            render(results, rawQuery);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Eventos de busca
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            searchInput.addEventListener('input', (e) => searchPosts(e.target.value));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById('scope').addEventListener('change', () =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              searchPosts(searchInput.value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              document.getElementById('tagFilter').addEventListener('input', () =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                searchPosts(searchInput.value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .getElementById('matchWhole')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .addEventListener('change', () => searchPosts(searchInput.value));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    clearBtn.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      searchInput.value = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById('tagFilter').value = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById('scope').value = 'all';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById('matchWhole').checked = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              searchInput.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                searchPosts('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Renderizar os posts ao carregar a página
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                render(postsData);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /* ===== BLOG DE ANA ALMEIDA - JAVASCRIPT ===== */

